using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Net.Sockets;
using System.Threading;
using System.Threading.Tasks;
using CommandCodeManager;
using ModernHost;
public static class ProxyWorkspaceChecks {
private static void Check(bool value,string message){if(!value)throw new Exception(message);}
private sealed class Handler:HttpMessageHandler {protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){throw new Exception("health check must not call upstream");}}
public static void Run(){CheckKeys().GetAwaiter().GetResult();CheckClients();Console.WriteLine("PASS proxy key migration/lifecycle, disabled-key rejection, strict eligibility, automatic recovery, client configuration merge/backup and malformed-file guards");}
private static async Task CheckKeys(){string original=LocalProxy.GenerateKey();var settings=new ProxySettings{Secret=Core.Encrypt(original)};ProxyWorkspace.Normalize(settings);Check(settings.AccessKeys.Count==1&&ProxyWorkspace.Primary(settings)==original,"legacy key migration failed");var created=ProxyWorkspace.Create(settings,"second");Check(created.Secret!=Core.Decrypt(created.Secret)&&settings.AccessKeys.Count==2,"new key not encrypted");var a=new ProxyAccount{Id="healthy",Name="healthy",Key="fixture-upstream",CredentialState="valid",QuotaKnown=true};var recovered=new ProxyAccount{Id="recovered",Name="recovered",Key="fixture-recovered",CredentialState="valid",QuotaKnown=true,BlockedUntil=DateTimeOffset.UtcNow.AddHours(1)};var unknown=new ProxyAccount{Id="unknown",Name="unknown",Key="fixture-unknown",CredentialState="valid",QuotaKnown=false};var probe=new TcpListener(IPAddress.Loopback,0);probe.Start();int port=((IPEndPoint)probe.LocalEndpoint).Port;probe.Stop();using(var gateway=new LocalProxy(()=>new[]{a,recovered,unknown},new Handler()))using(var client=new HttpClient(new HttpClientHandler{UseProxy=false}){BaseAddress=new Uri("http://127.0.0.1:"+port)}){gateway.Configure(port,original,new[]{a.Id},true);gateway.SetAccessKeys(ProxyWorkspace.EnabledKeys(settings));Check(gateway.CanJoin(a.Id)&&!gateway.CanJoin(recovered.Id)&&!gateway.CanJoin(unknown.Id),"unavailable or unverified account joinable");settings.AccountIds=new List<string>{a.Id,recovered.Id};Check(ProxyWorkspace.Reconcile(settings,gateway.JoinableIds()).SequenceEqual(new[]{a.Id}),"manual pool retained blocked account");settings.AutoJoin=true;recovered.BlockedUntil=null;var pool=ProxyWorkspace.Reconcile(settings,gateway.JoinableIds());Check(pool.Contains(recovered.Id)&&!pool.Contains(unknown.Id),"automatic pool failed recovery or included unverified account");gateway.SetPool(pool);client.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",Core.Decrypt(created.Secret));Check((await client.GetAsync("/health")).IsSuccessStatusCode,"new key rejected");created.Enabled=false;gateway.SetAccessKeys(ProxyWorkspace.EnabledKeys(settings));Check((int)(await client.GetAsync("/health")).StatusCode==401,"disabled key still accepted");client.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",original);Check((await client.GetAsync("/health")).IsSuccessStatusCode,"disabling one key disabled another");settings.AccessKeys.Clear();settings.Secret=null;ProxyWorkspace.Normalize(settings);Check(settings.AccessKeys.Count==0,"deleted key resurrected by migration");gateway.SetAccessKeys(ProxyWorkspace.EnabledKeys(settings));Check((int)(await client.GetAsync("/health")).StatusCode==401,"deleted keys still accepted");}}
private static Dictionary<string,object> Model(string id,string endpoint){return new Dictionary<string,object>{{"id",id},{"supported_endpoints",new[]{endpoint}}};}
private static void CheckClients(){string root=Path.Combine(Path.GetTempPath(),"workspace-client-check-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{string oc=Path.Combine(root,".config","opencode","opencode.jsonc");Directory.CreateDirectory(Path.GetDirectoryName(oc));File.WriteAllText(oc,"{\"theme\":\"existing\",\"provider\":{\"keep\":{\"options\":{\"apiKey\":\"fixture-original\"}}}, // keep theme\n}");var models=new[]{Model("opencode-go/kimi-k3","/v1/chat/completions"),Model("gpt-fixture","/v1/responses"),Model("claude-fixture","/v1/messages")};ProxyClientSetup.Write("opencode",root,null,"http://192.168.1.20:17766/v1","fixture-gateway",models);var config=Core.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(oc));Check(Core.Text(config,"theme")=="existing"&&Core.Object(Core.Value(Core.Object(Core.Value(config,"provider")),"keep")).Count>0,"OpenCode existing config lost");Check(Core.Text(config,"model").StartsWith("workspace-proxy-chat/")&&Core.Text(config,"small_model")==Core.Text(config,"model"),"OpenCode default models not routed");Check(Core.Object(Core.Value(config,"provider")).Count==4,"protocol-specific OpenCode providers missing");string cc=Path.Combine(root,".commandcode");Directory.CreateDirectory(cc);File.WriteAllText(Path.Combine(cc,"auth.json"),"{\"apiKey\":\"fixture-original-login\",\"other\":{\"key\":\"fixture-keep\"}}");File.WriteAllText(Path.Combine(cc,"providers.json"),"{\"provider\":{\"other\":{\"name\":\"keep\"}}}");string main=Path.Combine(root,"main.js");File.WriteAllText(main,"const MODEL_OPTIONS={};const DEFAULT_OSS_PROVIDER='fixture';const OPENAI_CHATCOMPLETE_SPEC={};const OPENAI_RESPONSES_SPEC={};");ProxyClientSetup.Write("commandcode",root,main,"http://192.168.1.20:17766/v1","fixture-gateway",models);ProxyClientSetup.Write("commandcode",root,main,"http://192.168.1.20:18888/v1","fixture-gateway",models);var auth=Core.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(cc,"auth.json")));Check(Core.Text(auth,"apiKey")=="fixture-original-login"&&Core.Object(Core.Value(auth,"other")).Count>0,"Command Code login overwritten");Check(File.ReadAllText(main).Split(new[]{"/* >>> multi-account-proxy-models >>> */"},StringSplitOptions.None).Length==2,"duplicate desktop model injection");var provider=Core.Object(Core.Value(Core.Object(Core.Value(Core.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(cc,"providers.json"))),"provider")),"workspace-proxy"));Check(Core.Text(provider,"baseURL").Contains("18888")&&Core.Object(Core.Value(provider,"models")).Count==3,"Command Code route configuration missing");Check(Directory.GetFiles(root,"*.encrypted",SearchOption.AllDirectories).Length>=3,"encrypted backups missing");File.WriteAllText(oc,"malformed fixture");bool rejected=false;try{ProxyClientSetup.Write("opencode",root,null,"http://192.168.1.20/v1","fixture",models);}catch(InvalidOperationException){rejected=true;}Check(rejected&&File.ReadAllText(oc)=="malformed fixture","malformed configuration destroyed");}finally{string full=Path.GetFullPath(root);if(!full.StartsWith(Path.GetFullPath(Path.GetTempPath()),StringComparison.OrdinalIgnoreCase))throw new Exception("temporary path escaped");Directory.Delete(full,true);}}
}
